#!/usr/bin/env python3
"""Regenerate the hand-crafted adversarial fixtures in this directory.

Each fixture targets one specific, documented rejection path in
``matplotlib_extension.package`` or ``matplotlib_extension.container``
(see ``docs/EDITABLE_FORMAT.md``'s Resource Limits and Security Boundary
sections). ``tests/test_malformed_fixtures.py`` reads ``index.json`` and
asserts that every fixture is rejected deterministically, by exact
exception type and message substring, not just "raises something".

Run this script (``uv run python tests/fixtures/malformed/generate_fixtures.py``)
only when adding or deliberately changing a fixture; the generated bytes are
committed so the test suite does not depend on being able to re-derive them
(and so a change to a fixture's exact bytes is visible in review).
"""

from __future__ import annotations

import json
import re
import struct
import sys
import zipfile
from io import BytesIO
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

import matplotlib.pyplot as plt  # noqa: E402
import olefile  # noqa: E402
from fuzz_support import (  # noqa: E402
    inflate_declared_entry_size,
    package_files,
    patch_figure_json,
    simple_figure,
    write_package,
)

from matplotlib_extension.container import (  # noqa: E402
    CFB_SIGNATURE,
    OLE_STREAM,
    PNG_CHUNK,
    PNG_SIGNATURE,
    embed_ole,
    embed_png,
    embed_svg,
)
from matplotlib_extension.package import (  # noqa: E402
    MAX_ARRAY_BYTES,
    dump_package,
)

OUT_DIR = Path(__file__).resolve().parent
INDEX: list[dict[str, str]] = []


def register(name: str, data: bytes, *, loader: str, error: str) -> None:
    (OUT_DIR / name).write_bytes(data)
    INDEX.append({"file": name, "loader": loader, "error": error})


def _valid_payload() -> bytes:
    fig = simple_figure()
    try:
        return dump_package(fig)
    finally:
        plt.close(fig)


def build_zip_fixtures() -> None:
    payload = _valid_payload()
    files = package_files(payload)

    register(
        "truncated_zip.bin",
        payload[: len(payload) - 200],
        loader="load_package",
        error="Invalid figure package ZIP",
    )

    traversal = dict(files)
    traversal["../escape.npy"] = b"\x00"
    register(
        "path_traversal_dotdot.bin",
        write_package(traversal),
        loader="load_package",
        error="Unsafe package path",
    )

    absolute = dict(files)
    absolute["/etc/passwd"] = b"\x00"
    register(
        "path_traversal_absolute.bin",
        write_package(absolute),
        loader="load_package",
        error="Unsafe package path",
    )

    backslash = dict(files)
    backslash["arrays\\evil.npy"] = b"\x00"
    register(
        "path_backslash.bin",
        write_package(backslash),
        loader="load_package",
        error="Unsafe package path",
    )

    output = BytesIO()
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_STORED) as archive:
        archive.writestr("manifest.json", files["manifest.json"])
        archive.writestr("figure.json", files["figure.json"])
        archive.writestr("figure.json", files["figure.json"])
    register(
        "duplicate_entries.bin",
        output.getvalue(),
        loader="load_package",
        error="Duplicate package entries are forbidden",
    )

    unlisted = dict(files)
    unlisted["arrays/99999999.npy"] = b"\x93NUMPY\x00\x00extra-unlisted-file"
    register(
        "unlisted_extra_file.bin",
        write_package(unlisted),
        loader="load_package",
        error="Package contains unlisted files",
    )

    mismatched = dict(files)
    patch_figure_json(mismatched, lambda spec: spec.__setitem__("schema_version", 1))
    register(
        "schema_version_cross_mismatch.bin",
        write_package(mismatched),
        loader="load_package",
        error="Unsupported figure schema version",
    )

    array_name = next(name for name in files if name.startswith("arrays/"))
    inflated = inflate_declared_entry_size(
        write_package(files), array_name, MAX_ARRAY_BYTES + 1
    )
    register(
        "oversized_array_declared_size.bin",
        inflated,
        loader="load_package",
        error="Package entry exceeds the size limit",
    )


def build_png_fixtures() -> None:
    fig = simple_figure()
    try:
        rendered = BytesIO()
        fig.savefig(rendered, format="png")
        editable = bytearray(embed_png(rendered.getvalue(), _valid_payload()))
    finally:
        plt.close(fig)

    bad_crc = bytearray(editable)
    chunk_index = bad_crc.index(PNG_CHUNK)
    bad_crc[chunk_index + 10] ^= 0xFF  # flip a byte inside the payload, not the CRC
    register(
        "png_bad_crc.bin",
        bytes(bad_crc),
        loader="extract_png",
        error="Editable PNG chunk failed its CRC check",
    )

    # Duplicate the mpFg chunk verbatim (editable payload appears twice).
    position = len(PNG_SIGNATURE)
    chunk_start = editable.index(PNG_CHUNK, position) - 4
    length = struct.unpack(">I", bytes(editable[chunk_start : chunk_start + 4]))[0]
    chunk_bytes = bytes(editable[chunk_start : chunk_start + 12 + length])
    duplicated = (
        bytes(editable[:chunk_start]) + chunk_bytes + bytes(editable[chunk_start:])
    )
    register(
        "png_duplicate_chunks.bin",
        duplicated,
        loader="extract_png",
        error="exactly one editable payload",
    )


def build_pdf_fixtures() -> None:
    fig = simple_figure()
    try:
        rendered = BytesIO()
        fig.savefig(rendered, format="pdf")
        plain_pdf = rendered.getvalue()
    finally:
        plt.close(fig)
    register(
        "pdf_no_attachment.bin",
        plain_pdf,
        loader="extract_pdf",
        error="Invalid PDF file",
    )


def build_svg_fixtures() -> None:
    fig = simple_figure()
    try:
        rendered = BytesIO()
        fig.savefig(rendered, format="svg")
        editable = embed_svg(rendered.getvalue(), _valid_payload())
    finally:
        plt.close(fig)

    # Must stay inside the extraction regex's own character class
    # ([A-Za-z0-9+/=\r\n]) so it is still *found*, but decode to invalid
    # base64 (wrong length/padding) so `base64.b64decode(..., validate=True)`
    # itself raises.
    bad_base64 = re.sub(
        rb'encoding="base64">([A-Za-z0-9+/=\r\n]+)</mplex:package>',
        b'encoding="base64">A</mplex:package>',
        editable,
        count=1,
    )
    register(
        "svg_bad_base64.bin",
        bad_base64,
        loader="extract_svg",
        error="Invalid base64 SVG payload",
    )

    match = re.search(rb"<metadata>.*?</metadata>", editable, re.DOTALL)
    assert match is not None
    duplicated = editable[: match.end()] + match.group(0) + editable[match.end() :]
    register(
        "svg_duplicate_payload.bin",
        duplicated,
        loader="extract_svg",
        error="exactly one editable payload",
    )


def _find_directory_entry_offset(data: bytes, encoded_name: bytes) -> int:
    """Byte offset of the 128-byte directory entry whose name field starts
    with *encoded_name* (the entry's name field is its first 64 bytes)."""
    index = data.find(encoded_name)
    assert index != -1, f"directory entry for {encoded_name!r} not found"
    return index


def build_ole_fixtures() -> None:
    fig = simple_figure()
    try:
        rendered = BytesIO()
        fig.savefig(rendered, format="png")
        editable_png = embed_png(rendered.getvalue(), _valid_payload())
        ole = embed_ole(editable_png)
    finally:
        plt.close(fig)
    assert ole[:8] == CFB_SIGNATURE

    with olefile.OleFileIO(BytesIO(ole)) as container:
        sector_size = container.sector_size
        stream_entry = next(
            entry
            for entry in container.direntries
            if entry is not None and entry.name == OLE_STREAM
        )
        native = container.openstream(OLE_STREAM).read()
    # The CFB header always occupies exactly one full sector; sector N's
    # bytes start right after it.
    stream_byte_offset = sector_size + stream_entry.isectStart * sector_size

    # Directory entry layout (128 bytes, see `_directory_entry` in
    # matplotlib_extension/container.py): name(64) name_len(H) object_type(B)
    # color(B) left(I) right(I) child(I) clsid(16) state(I) ctime(Q) mtime(Q)
    # start_sector(I) stream_size(Q) -- stream_size is the trailing 8 bytes.
    encoded_name = (OLE_STREAM + "\x00").encode("utf-16le")
    entry_offset = _find_directory_entry_offset(ole, encoded_name)

    wrong_name = bytearray(ole)
    replacement_name = "WrongStream\x00".encode("utf-16le")
    wrong_name[entry_offset : entry_offset + len(replacement_name)] = replacement_name
    wrong_name[entry_offset + len(replacement_name) : entry_offset + 64] = bytes(
        64 - len(replacement_name)
    )
    struct.pack_into("<H", wrong_name, entry_offset + 64, len(replacement_name))
    register(
        "ole_wrong_stream_name.bin",
        bytes(wrong_name),
        loader="extract_ole_native_png",
        error="OLE container has unexpected streams or storages",
    )

    # Shrink the directory entry's *declared* stream_size (the trailing 8
    # bytes of the 128-byte entry) well below the real native header's fixed
    # fields, without touching the actual sector bytes. olefile itself
    # rejects the inconsistent stream/sector-chain length while opening the
    # stream, before this project's own "< 32 bytes" truncation check can
    # run; the broad `except Exception` in `extract_ole_native_png` still
    # turns that into a deterministic `PackageError`.
    tiny_stream = bytearray(ole)
    stream_size_offset = entry_offset + 128 - 8
    struct.pack_into("<Q", tiny_stream, stream_size_offset, 10)
    register(
        "ole_truncated_native.bin",
        bytes(tiny_stream),
        loader="extract_ole_native_png",
        error="Invalid OLE compound file",
    )

    # Corrupt the native stream's self-reported total_size (its own first 4
    # bytes), which must equal len(stream) - 4. The stream's sector-aligned
    # byte offset was resolved above via the FAT chain, so patch it directly
    # instead of searching for the value (which could collide elsewhere).
    real_total_size = struct.unpack_from("<I", native, 0)[0]
    assert real_total_size == len(native) - 4
    bad_size = bytearray(ole)
    struct.pack_into("<I", bad_size, stream_byte_offset, real_total_size + 5)
    register(
        "ole_size_mismatch.bin",
        bytes(bad_size),
        loader="extract_ole_native_png",
        error="OLE native stream size is invalid",
    )


def main() -> None:
    INDEX.clear()
    build_zip_fixtures()
    build_png_fixtures()
    build_pdf_fixtures()
    build_svg_fixtures()
    build_ole_fixtures()
    (OUT_DIR / "index.json").write_text(
        json.dumps(INDEX, indent=2, sort_keys=True) + "\n"
    )
    print(f"Wrote {len(INDEX)} fixtures to {OUT_DIR}")


if __name__ == "__main__":
    main()
